      + "function sun(n){var st=Date.UTC(n.getUTCFullYear(),0,0),doy=Math.floor((n.getTime()-st)/86400000),dec=-23.44*Math.cos(2*Math.PI/365*(doy+10)),B=2*Math.PI/365*(doy-81),eot=9.87*Math.sin(2*B)-7.53*Math.cos(B)-1.5*Math.sin(B),h=n.getUTCHours()+n.getUTCMinutes()/60+n.getUTCSeconds()/3600,sl=-15*((h+eot/60)-12);while(sl>180)sl-=360;while(sl<-180)sl+=360;return{dec:dec,slon:sl,eot:eot};}"
      + "function tl(lon,s){var ha=(lon-s.slon)*Math.PI/180,td=Math.tan(s.dec*Math.PI/180);if(Math.abs(td)<1e-4)td=td<0?-1e-4:1e-4;return Math.atan(-Math.cos(ha)/td)*180/Math.PI;}"
      + "function draw(){var W=cv.offsetWidth||700,H=Math.round(W/2);cv.width=W*2;cv.height=H*2;cv.style.height=H+'px';var c=cv.getContext('2d');c.setTransform(2,0,0,2,0,0);c.fillStyle='#16395a';c.fillRect(0,0,W,H);c.fillStyle='#3d6b8f';c.strokeStyle='#4f80a6';c.lineWidth=.6;"
      + "LAND.forEach(function(g){var p=g.p;c.beginPath();p.forEach(function(q,i){var x=(q[0]+180)/360*W,y=(90-q[1])/180*H;if(i)c.lineTo(x,y);else c.moveTo(x,y);});c.closePath();c.fill();c.stroke();});"
      + "var s=sun(new Date()),xy=function(lo,la){return[(lo+180)/360*W,(90-la)/180*H];};c.beginPath();for(var x=0;x<=W;x+=2){var lo=x/W*360-180,p=xy(lo,tl(lo,s));if(x)c.lineTo(p[0],p[1]);else c.moveTo(p[0],p[1]);}if(s.dec>=0){c.lineTo(W,H);c.lineTo(0,H);}else{c.lineTo(W,0);c.lineTo(0,0);}c.closePath();c.fillStyle='rgba(2,6,16,.68)';c.fill();"
      + "c.beginPath();for(var x2=0;x2<=W;x2+=2){var lo2=x2/W*360-180,p2=xy(lo2,tl(lo2,s));if(x2)c.lineTo(p2[0],p2[1]);else c.moveTo(p2[0],p2[1]);}c.strokeStyle='rgba(224,92,74,.28)';c.lineWidth=10;c.stroke();c.strokeStyle='rgba(255,140,100,.9)';c.lineWidth=1.5;c.stroke();"
      + "var sp=xy(s.slon,s.dec);c.fillStyle='#ffd766';c.beginPath();c.arc(sp[0],sp[1],4,0,7);c.fill();if(LOC){var lp=xy(LOC[1],LOC[0]);c.fillStyle='#5fd38a';c.beginPath();c.arc(lp[0],lp[1],4,0,7);c.fill();}info(s);}"
      + "function info(s){var d=new Date(),t=('0'+d.getUTCHours()).slice(-2)+':'+('0'+d.getUTCMinutes()).slice(-2)+' UTC';var la,lo,src;if(LOC){la=LOC[0];lo=LOC[1];src='your location';}else{lo=-d.getTimezoneOffset()/4;la=35;src='your time zone (approximate; share location for exact times)';}"
      + "var cosH=-Math.tan(la*Math.PI/180)*Math.tan(s.dec*Math.PI/180);var h='Map time: <b>'+t+'</b>. Yellow dot = Sun overhead; orange line = grey line.';if(cosH>=-1&&cosH<=1){var H0=Math.acos(cosH)*180/Math.PI,noon=720-4*lo-s.eot,rise=noon-4*H0-3,set=noon+4*H0+3;function f(m){m=((Math.round(m)%1440)+1440)%1440;var u=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),0,m));return ('0'+u.getUTCHours()).slice(-2)+('0'+u.getUTCMinutes()).slice(-2)+' UTC ('+u.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+' local)';}h+='<br>Sunrise: <b>'+f(rise)+'</b><br>Sunset: <b>'+f(set)+'</b><br><span class=\"small\">Based on '+src+'.</span>';}else h+='<br>No sunrise or sunset at this latitude today.';o.innerHTML=h;}"
